import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Button,
  Checkbox,
  Input,
  Modal,
  SearchTextInput,
  Select,
  Tabs,
  dispatchAppToast,
  LeaveConfirmModal,
  LinListFilterField,
  useDirtyTracking,
  useLeaveConfirm,
  type Tab,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { masterService } from '../../../services/master/masterService';
import { systemService } from '../../../services/system/systemService';
import type { PostingReasonRuleDto, ExpenseItemDto } from '../../../services/master/models';
import type { VoucherRegistryDto } from '../../../services/system/voucherRegistryModels';
import { normalizeCode } from '../../../utils/codeField';
import {
  formatAllowedVoucherLabel,
  joinAllowedVoucherTypeCodes,
  parseAllowedVoucherTypeCodes,
  POSTING_REASON_VOUCHER_DEFAULTS,
} from '../../../utils/postingReasonVoucherAccess';
import { scrollToFirstFieldError } from '../../../utils/catalogFormValidation';
import { useCatalogListSelection } from '../../../hooks/useCatalogListSelection';
import { useCatalogMasterListRowMenu } from '../../../hooks/useCatalogMasterListRowMenu';
import {
  CatalogCompanyField,
  useCatalogListPaging,
  useServerPagedListLoading,
  SharedCatalogFormActions,
  useSharedCatalog,
  sharedCatalogFormProps,
  isSharedCatalogReadOnly,
  CatalogListMasterLinPageLayout,
  CatalogFormHistorySlot,
  CatalogListHeaderFilters,
  CatalogRowActionMenu,
} from '../../../components/catalog';
import {
  CatalogListGridFromSchema,
  CatalogUiSchemaEditorModal,
  useCatalogUiSchema,
  listVisibleFields,
  proposalEditableFields,
  toProposalFieldDefs,
} from '../../../components/catalog/catalogUiSchema';
import type { CatalogBatchDeleteMode } from '../../../components/catalog';
import styles from '../../../styles/erpPage.module.css';

const TEST_ID = 'dm-dinh-khoan-nghiep-vu';
const CATALOG_KIND = 'posting-reason-rules';

type FormTabId = 'info' | 'costs' | 'vouchers';
type FormErrors = Partial<Record<'code' | 'name' | 'reasonGroup' | 'documentType' | 'debitAccountCode' | 'creditAccountCode', string>>;

function parseExpenseItemCodes(raw?: string | null): string[] {
  if (!raw?.trim()) return [];
  return raw.split(/[,;\n\r]+/).map(x => x.trim().toUpperCase()).filter(Boolean)
    .filter((v, i, a) => a.indexOf(v) === i);
}

function joinExpenseItemCodes(codes: string[]): string | undefined {
  const next = [...new Set(codes.map(c => c.trim().toUpperCase()).filter(Boolean))].sort();
  return next.length ? next.join(',') : undefined;
}

const DinhKhoanNghiepVuPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { onDirtyChange, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);
  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [voucherTypeFilter, setVoucherTypeFilter] = useState('');
  const [items, setItems] = useState<PostingReasonRuleDto[]>([]);
  const sessionCompanyName = useMemo(() => items[0]?.companyName, [items]);
  const [modalOpen, setModalOpen] = useState(false);
  const [formTab, setFormTab] = useState<FormTabId>('info');
  const [voucherPickSearch, setVoucherPickSearch] = useState('');
  const [expensePickSearch, setExpensePickSearch] = useState('');
  const [expenseItems, setExpenseItems] = useState<ExpenseItemDto[]>([]);
  const [editing, setEditing] = useState<PostingReasonRuleDto | null>(null);
  const [form, setForm] = useState<Partial<PostingReasonRuleDto>>({});
  const [errors, setErrors] = useState<FormErrors>({});
  const [saving, setSaving] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  const [viewOnlyShared, setViewOnlyShared] = useState(false);
  const [schemaEditorOpen, setSchemaEditorOpen] = useState(false);
  const [voucherRegistry, setVoucherRegistry] = useState<VoucherRegistryDto[]>([]);

  const allowedVoucherCodes = useMemo(
    () => parseAllowedVoucherTypeCodes(form.allowedVoucherTypeCodes),
    [form.allowedVoucherTypeCodes],
  );

  const filteredVoucherRegistry = useMemo(() => {
    const q = voucherPickSearch.trim().toLowerCase();
    if (!q) return voucherRegistry;
    return voucherRegistry.filter(v =>
      v.voucherTypeCode.toLowerCase().includes(q)
      || v.name.toLowerCase().includes(q)
      || (v.idCodePrefix ?? '').toLowerCase().includes(q),
    );
  }, [voucherRegistry, voucherPickSearch]);

  const formTabs = useMemo<Tab[]>(() => {
    const costCount = parseExpenseItemCodes(form.expenseItemCode).length;
    return [
      { id: 'info', label: 'Thông tin' },
      {
        id: 'costs',
        label: 'Cấu hình chi phí',
        badge: costCount > 0 ? String(costCount) : undefined,
        badgeColor: (costCount > 0 ? 'primary' : 'gray') as 'primary' | 'gray',
      },
      {
        id: 'vouchers',
        label: 'Chứng từ được phép',
        badge: allowedVoucherCodes.length > 0 ? String(allowedVoucherCodes.length) : 'Tất cả',
        badgeColor: (allowedVoucherCodes.length > 0 ? 'primary' : 'gray') as 'primary' | 'gray',
      },
    ];
  }, [allowedVoucherCodes.length, form.expenseItemCode]);

  useEffect(() => {
    let cancelled = false;
    systemService.getVoucherRegistry()
      .then(rows => {
        if (!cancelled) setVoucherRegistry(rows.filter(r => r.isActive));
      })
      .catch(() => {
        if (!cancelled) setVoucherRegistry([]);
      });
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    let cancelled = false;
    masterService.getExpenseItems()
      .then(rows => { if (!cancelled) setExpenseItems(rows.filter(r => r.isActive)); })
      .catch(() => { if (!cancelled) setExpenseItems([]); });
    return () => { cancelled = true; };
  }, []);

  const voucherTypeFilterOptions = useMemo(() => {
    const cashVoucherTypes = new Set<string>([
      POSTING_REASON_VOUCHER_DEFAULTS.cashReceipt,
      POSTING_REASON_VOUCHER_DEFAULTS.cashPayment,
      'giay-bao-co',
      'giay-bao-no',
      'uy-nhiem-chi',
      'chuyen-tien-noi-bo',
    ]);
    const opts = voucherRegistry
      .filter(v => cashVoucherTypes.has(v.voucherTypeCode))
      .map(v => ({ value: v.voucherTypeCode, label: `${v.name} (${v.voucherTypeCode})` }));
    return [{ value: '', label: 'Tất cả loại chứng từ' }, ...opts];
  }, [voucherRegistry]);

  const toggleAllowedVoucher = useCallback((voucherTypeCode: string, checked: boolean) => {
    markDirty();
    const next = new Set(allowedVoucherCodes);
    if (checked) next.add(voucherTypeCode);
    else next.delete(voucherTypeCode);
    setForm(f => ({
      ...f,
      allowedVoucherTypeCodes: joinAllowedVoucherTypeCodes([...next]),
    }));
  }, [allowedVoucherCodes, markDirty]);

  const clearAllowedVouchers = useCallback(() => {
    markDirty();
    setForm(f => ({ ...f, allowedVoucherTypeCodes: undefined }));
  }, [markDirty]);

  /** Khoản chi phí đã gắn (CSV → list). */
  const selectedExpenseCodes = useMemo(
    () => parseExpenseItemCodes(form.expenseItemCode),
    [form.expenseItemCode],
  );

  /** Danh sách khoản chi phí lọc theo từ khóa tìm kiếm (hiện cả đã gắn ĐK khác — disable). */
  const filteredExpenseItems = useMemo(() => {
    const q = expensePickSearch.trim().toLowerCase();
    if (!q) return [];
    return expenseItems.filter(e =>
      e.code.toLowerCase().includes(q)
      || e.name.toLowerCase().includes(q),
    ).slice(0, 20);
  }, [expenseItems, expensePickSearch]);

  const toggleExpenseCode = useCallback((code: string, add: boolean) => {
    markDirty();
    setForm(f => {
      const cur = parseExpenseItemCodes(f.expenseItemCode);
      const next = add
        ? [...cur, code.toUpperCase()]
        : cur.filter(c => c !== code.toUpperCase());
      return { ...f, expenseItemCode: joinExpenseItemCodes(next) };
    });
    if (add) setExpensePickSearch('');
  }, [markDirty]);

  const clearExpenseCodes = useCallback(() => {
    markDirty();
    setForm(f => ({ ...f, expenseItemCode: undefined }));
  }, [markDirty]);

  /** Danh sách chứng từ có thể thêm: lọc theo từ khóa tìm kiếm + loại trừ đã chọn. */
  const availableToAdd = useMemo(() => {
    if (!voucherPickSearch.trim()) return [];
    return filteredVoucherRegistry.filter(v => !allowedVoucherCodes.includes(v.voucherTypeCode));
  }, [filteredVoucherRegistry, allowedVoucherCodes, voucherPickSearch]);

  const { schema, reload: reloadSchema } = useCatalogUiSchema(CATALOG_KIND);
  const listColumns = useMemo(() => listVisibleFields(schema), [schema]);
  const proposalFieldDefs = useMemo(
    () => toProposalFieldDefs(proposalEditableFields(schema)),
    [schema],
  );

  const { page, setPage, pageSize, setPageSize, resetPage } = useCatalogListPaging();
  const {
    showTableLoading,
    pageLoading,
    pulseSearch,
    setLoadingMode,
    beginFetch,
    endFetch,
  } = useServerPagedListLoading();

  const totalCount = items.length;
  const pagedItems = useMemo(() => {
    const start = (page - 1) * pageSize;
    return items.slice(start, start + pageSize);
  }, [items, page, pageSize]);

  const selection = useCatalogListSelection({
    rows: pagedItems,
    totalCount,
    page,
    pageSize,
    getRowId: r => r.id,
    isRowSelectable: () => true,
  });

  const refresh = () => {
    setLoadingMode('filter');
    selection.clearSelection();
    setReloadKey(k => k + 1);
  };
  const shared = useSharedCatalog(CATALOG_KIND, refresh);
  const sharedForm = sharedCatalogFormProps(CATALOG_KIND, shared);

  const handleSearch = () => {
    pulseSearch(() => {
      setLoadingMode('filter');
      setSearch(searchDraft.trim());
      resetPage();
      selection.clearSelection();
    });
  };

  React.useEffect(() => {
    let cancelled = false;
    beginFetch();
    const t = setTimeout(() => {
      masterService.getPostingReasonRules({
        search: search || undefined,
        voucherTypeCode: voucherTypeFilter || undefined,
      })
        .then(data => { if (!cancelled) setItems(data); })
        .catch(err => {
          if (!cancelled) dispatchAppToast(dispatch, { message: err?.message ?? 'Lỗi tải quy tắc định khoản', type: 'error' });
        })
        .finally(() => { if (!cancelled) endFetch(); });
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  }, [search, voucherTypeFilter, reloadKey, dispatch]);

  const clearFieldError = (key: keyof FormErrors) => {
    setErrors(prev => {
      if (!prev[key]) return prev;
      const next = { ...prev };
      delete next[key];
      return next;
    });
  };

  const validate = (): FormErrors => {
    const next: FormErrors = {};
    if (!form.code?.trim()) next.code = 'Nhập mã quy tắc';
    if (!form.name?.trim()) next.name = 'Nhập tên nghiệp vụ';
    if (!form.reasonGroup?.trim()) next.reasonGroup = 'Nhập nhóm nghiệp vụ';
    if (!form.documentType?.trim()) next.documentType = 'Nhập loại chứng từ';
    if (!form.debitAccountCode?.trim()) next.debitAccountCode = 'Nhập TK Nợ';
    if (!form.creditAccountCode?.trim()) next.creditAccountCode = 'Nhập TK Có';
    return next;
  };

  const closeFormModal = () => {
    setModalOpen(false);
    markClean();
  };

  const openAdd = () => {
    setViewOnlyShared(false);
    setEditing(null);
    setForm({});
    setErrors({});
    setFormTab('info');
    setVoucherPickSearch('');
    setExpensePickSearch('');
    markClean();
    setModalOpen(true);
  };

  const openView = useCallback((row: PostingReasonRuleDto) => {
    setViewOnlyShared(true);
    setEditing(row);
    setForm({ ...row });
    setErrors({});
    setFormTab('info');
    setVoucherPickSearch('');
    setExpensePickSearch('');
    markClean();
    setModalOpen(true);
  }, [markClean]);

  const openEditImpl = useCallback((row: PostingReasonRuleDto) => {
    setViewOnlyShared(false);
    setEditing(row);
    setForm({ ...row });
    setErrors({});
    setFormTab('info');
    setVoucherPickSearch('');
    setExpensePickSearch('');
    markClean();
    setModalOpen(true);
  }, [markClean]);

  const rowMenu = useCatalogMasterListRowMenu({
    testIdPrefix: TEST_ID,
    catalogKind: CATALOG_KIND,
    selection,
    openEdit: openEditImpl,
    openView,
  });

  const handleSave = async () => {
    const nextErrors = validate();
    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      scrollToFirstFieldError(TEST_ID);
      return;
    }
    setSaving(true);
    try {
      if (editing) await masterService.updatePostingReasonRule(editing.id, form);
      else await masterService.createPostingReasonRule(form);
      dispatchAppToast(dispatch, { message: editing ? 'Cập nhật quy tắc định khoản thành công' : 'Tạo quy tắc định khoản thành công', type: 'success' });
      markClean();
      setModalOpen(false);
      refresh();
    } catch (err: unknown) {
      dispatchAppToast(dispatch, { message: err instanceof Error ? err.message : 'Lưu thất bại', type: 'error' });
    } finally {
      setSaving(false);
    }
  };

  const handleBatchDelete = async (mode: CatalogBatchDeleteMode) => {
    const ids =
      selection.selectionMode === 'all'
        ? items.filter(r => !isSharedCatalogReadOnly(r)).map(r => r.id)
        : [...selection.selectedIds].filter(id => {
            const row = pagedItems.find(r => r.id === id) ?? items.find(r => r.id === id);
            return row && !isSharedCatalogReadOnly(row);
          });
    if (ids.length === 0) throw new Error('Không có bản ghi hợp lệ để xóa');
    if (mode === 'soft') {
      await Promise.all(ids.map(id => {
        const row = items.find(r => r.id === id)!;
        return masterService.updatePostingReasonRule(id, { ...row, isActive: false });
      }));
      dispatchAppToast(dispatch, { message: `Đã ngưng ${ids.length} quy tắc định khoản`, type: 'success' });
    } else {
      await Promise.all(ids.map(id => masterService.deletePostingReasonRule(id)));
      dispatchAppToast(dispatch, { message: `Đã xóa ${ids.length} quy tắc định khoản`, type: 'success' });
    }
    refresh();
  };

  const filterBar = (
    <CatalogListHeaderFilters testIdPrefix={TEST_ID} filterMaxWidthPx={1000} filterCols={2} filterLayout="compact">
      <LinListFilterField testId={`${TEST_ID}-field-search`}>
        <SearchTextInput
          label="Tìm kiếm"
          placeholder="Tìm mã, tên..."
          value={searchDraft}
          onChange={setSearchDraft}
          onSearch={handleSearch}
          testId={`${TEST_ID}-search-text`}
        />
      </LinListFilterField>
      <LinListFilterField testId={`${TEST_ID}-field-voucherType`}>
        <Select
          label="Loại chứng từ"
          value={voucherTypeFilter}
          placeholder="Tất cả loại chứng từ"
          options={voucherTypeFilterOptions}
          onChange={e => {
            setLoadingMode('filter');
            setVoucherTypeFilter(e.target.value);
            resetPage();
            selection.clearSelection();
          }}
          data-testid={`${TEST_ID}-voucher-type-filter`}
        />
      </LinListFilterField>
    </CatalogListHeaderFilters>
  );

  return (
    <>
      <CatalogListMasterLinPageLayout
        testIdPrefix={TEST_ID}
        catalogKind={CATALOG_KIND}
        shared={shared}
        selection={selection}
        totalCount={totalCount}
        selectableOnPage={pagedItems.filter(r => !isSharedCatalogReadOnly(r))}
        onAdd={openAdd}
        onEdit={rowMenu.openEditWithPerm}
        onRefresh={refresh}
        onBatchDelete={handleBatchDelete}
        showSchemaConfig
        onOpenSchemaConfig={() => setSchemaEditorOpen(true)}
        proposalFieldDefs={proposalFieldDefs.length > 0 ? proposalFieldDefs : undefined}
        toolbarBridgeRef={rowMenu.toolbarBridgeRef}
        page={page}
        pageSize={pageSize}
        onPageChange={p => { setLoadingMode('page'); setPage(p); selection.clearSelection(); }}
        onPageSizeChange={size => { setLoadingMode('filter'); setPageSize(size); }}
        showTableLoading={showTableLoading}
        pageLoading={pageLoading}
        header={{ title: 'Quy tắc định khoản', titleIconClass: 'fas fa-balance-scale' }}
        listTitle="Danh sách quy tắc định khoản"
        listRowMenuHelp
        filtersTestId={`${TEST_ID}-filters`}
        filterMaxWidthPx={1000}
        filters={filterBar}
        schemaEditorModal={(
          <CatalogUiSchemaEditorModal
            testIdPrefix={TEST_ID}
            catalogKind={CATALOG_KIND}
            isOpen={schemaEditorOpen}
            onClose={() => setSchemaEditorOpen(false)}
            onSaved={() => {
              reloadSchema();
              refresh();
            }}
          />
        )}
        extraModals={(
          <>
            <CatalogRowActionMenu {...rowMenu.rowActionMenuProps} />
            <LeaveConfirmModal {...leaveConfirmModalProps} />
          </>
        )}
      >
        {pagedItems.length === 0 ? (
          <div className={styles.empty}>
            <i className="fas fa-inbox" />
            <p>{search.trim() ? 'Không tìm thấy mẫu phù hợp' : 'Không có dữ liệu'}</p>
          </div>
        ) : listColumns.length > 0 ? (
          <CatalogListGridFromSchema
            testIdPrefix={TEST_ID}
            rows={pagedItems}
            page={page}
            pageSize={pageSize}
            columns={listColumns}
            schema={schema}
            selection={selection}
            getRowId={r => r.id}
            isRowSelectable={r => !isSharedCatalogReadOnly(r)}
            {...rowMenu.gridRowMenuProps}
          />
        ) : null}
      </CatalogListMasterLinPageLayout>

      <Modal
        isOpen={modalOpen}
        onClose={closeFormModal}
        title={viewOnlyShared ? 'Xem quy tắc định khoản dùng chung' : editing ? 'Sửa quy tắc định khoản' : 'Thêm quy tắc định khoản'}
      >
        <div className={styles.modalBody} data-testid={`${TEST_ID}-form`}>
          <Tabs
            tabs={formTabs}
            activeTab={formTab}
            onTabChange={id => setFormTab(id as FormTabId)}
            variant="underline"
          />

          {formTab === 'info' && (
          <div className={styles.formGrid}>
            <div className={styles.masterCodeNameRow}>
              <div className={styles.field} data-testid={`${TEST_ID}-field-code`}>
                <label className={styles.label}>Mã *</label>
                <Input
                  value={form.code ?? ''}
                  disabled={!!editing}
                  error={errors.code}
                  className={styles.codeInput}
                  onChange={e => {
                    markDirty();
                    clearFieldError('code');
                    setForm(f => ({ ...f, code: normalizeCode(e.target.value) }));
                  }}
                />
              </div>
              <div className={styles.field} data-testid={`${TEST_ID}-field-name`}>
                <label className={styles.label}>Tên *</label>
                <Input
                  value={form.name ?? ''}
                  disabled={viewOnlyShared}
                  error={errors.name}
                  onChange={e => {
                    markDirty();
                    clearFieldError('name');
                    setForm(f => ({ ...f, name: e.target.value }));
                  }}
                />
              </div>
            </div>
            <div className={styles.masterCodeNameRow}>
              <div className={styles.field} data-testid={`${TEST_ID}-field-reasonGroup`}>
                <label className={styles.label}>Nhóm *</label>
                <Input
                  value={form.reasonGroup ?? ''}
                  disabled={viewOnlyShared}
                  error={errors.reasonGroup}
                  placeholder="BAOCO, PT, CCH..."
                  onChange={e => {
                    markDirty();
                    clearFieldError('reasonGroup');
                    setForm(f => ({ ...f, reasonGroup: e.target.value }));
                  }}
                />
              </div>
              <div className={styles.field} data-testid={`${TEST_ID}-field-documentType`}>
                <label className={styles.label}>Loại CT FM *</label>
                <Input
                  value={form.documentType ?? ''}
                  disabled={viewOnlyShared}
                  error={errors.documentType}
                  placeholder="T, BC, C..."
                  onChange={e => {
                    markDirty();
                    clearFieldError('documentType');
                    setForm(f => ({ ...f, documentType: e.target.value }));
                  }}
                />
              </div>
            </div>
            <div className={styles.masterCodeNameRow}>
              <div className={styles.field} data-testid={`${TEST_ID}-field-debitAccountCode`}>
                <label className={styles.label}>TK Nợ FM *</label>
                <Input
                  value={form.debitAccountCode ?? ''}
                  disabled={viewOnlyShared}
                  error={errors.debitAccountCode}
                  placeholder="911..."
                  onChange={e => {
                    markDirty();
                    clearFieldError('debitAccountCode');
                    setForm(f => ({ ...f, debitAccountCode: e.target.value }));
                  }}
                />
              </div>
              <div className={styles.field} data-testid={`${TEST_ID}-field-creditAccountCode`}>
                <label className={styles.label}>TK Có FM *</label>
                <Input
                  value={form.creditAccountCode ?? ''}
                  disabled={viewOnlyShared}
                  error={errors.creditAccountCode}
                  placeholder="421..."
                  onChange={e => {
                    markDirty();
                    clearFieldError('creditAccountCode');
                    setForm(f => ({ ...f, creditAccountCode: e.target.value }));
                  }}
                />
              </div>
            </div>
            <div className={styles.masterCodeNameRow}>
              <div className={styles.field} data-testid={`${TEST_ID}-field-erpDebitAccountCode`}>
                <label className={styles.label}>TK Nợ ERP</label>
                <Input
                  value={form.erpDebitAccountCode ?? ''}
                  disabled={viewOnlyShared}
                  placeholder="5111, 1131..."
                  onChange={e => {
                    markDirty();
                    setForm(f => ({ ...f, erpDebitAccountCode: e.target.value }));
                  }}
                />
              </div>
              <div className={styles.field} data-testid={`${TEST_ID}-field-erpCreditAccountCode`}>
                <label className={styles.label}>TK Có ERP</label>
                <Input
                  value={form.erpCreditAccountCode ?? ''}
                  disabled={viewOnlyShared}
                  placeholder="5111, 1311..."
                  onChange={e => {
                    markDirty();
                    setForm(f => ({ ...f, erpCreditAccountCode: e.target.value }));
                  }}
                />
              </div>
            </div>
            <div className={styles.field} data-testid={`${TEST_ID}-field-suggestOnly`}>
              <Checkbox
                label="Gợi ý tài khoản (user sửa được ngay)"
                checked={form.suggestOnly ?? false}
                disabled={viewOnlyShared}
                onChange={e => {
                  markDirty();
                  setForm(f => ({ ...f, suggestOnly: e.target.checked, allowEditPostingAccounts: e.target.checked ? false : f.allowEditPostingAccounts }));
                }}
                data-testid={`${TEST_ID}-field-suggestOnly-cb`}
              />
            </div>
          </div>
          )}

          {formTab === 'costs' && (
            <div style={{ paddingTop: 16 }} data-testid={`${TEST_ID}-tab-costs`}>
              <p style={{ margin: '0 0 14px', fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6b7280)' }}>
                Một định khoản có thể gắn nhiều mã chi phí. Mã đã cấu hình ở ĐK khác vẫn hiện khi tìm — disabled kèm cảnh báo.
                Từ khóa grep nhập trên danh mục chi phí.
              </p>

              {!viewOnlyShared && (
                <div style={{ marginBottom: 14 }}>
                  <SearchTextInput
                    label="Tìm và thêm mã chi phí"
                    placeholder="Tìm mã hoặc tên khoản chi phí..."
                    value={expensePickSearch}
                    onChange={setExpensePickSearch}
                    onSearch={() => {}}
                    testId={`${TEST_ID}-expense-pick-search`}
                  />
                  {filteredExpenseItems.length > 0 && (
                    <div style={{
                      border: '1px solid var(--color-border, #e5e7eb)',
                      borderRadius: 6, marginTop: 4, overflow: 'hidden',
                      maxHeight: 220, overflowY: 'auto',
                    }}>
                      {filteredExpenseItems.map(e => {
                        const assignedOther = e.assignedPostingReasonCode
                          && e.assignedPostingReasonCode.toUpperCase() !== (form.code ?? '').toUpperCase()
                          && !selectedExpenseCodes.includes(e.code.toUpperCase());
                        const already = selectedExpenseCodes.includes(e.code.toUpperCase());
                        const disabled = !!assignedOther || already || viewOnlyShared;
                        return (
                          <button
                            key={e.code}
                            type="button"
                            disabled={disabled}
                            onClick={() => {
                              if (disabled) return;
                              toggleExpenseCode(e.code, true);
                            }}
                            style={{
                              display: 'flex', alignItems: 'center', gap: 8,
                              width: '100%', textAlign: 'left',
                              padding: '8px 12px', background: assignedOther ? '#fff7ed' : 'none', border: 'none',
                              borderBottom: '1px solid var(--color-border, #e5e7eb)',
                              cursor: disabled ? 'not-allowed' : 'pointer', fontSize: '0.875rem',
                              opacity: disabled ? 0.75 : 1,
                            }}
                            data-testid={`${TEST_ID}-select-expense-${e.code}`}
                            title={assignedOther ? `Đã cấu hình ở định khoản ${e.assignedPostingReasonCode}` : undefined}
                          >
                            <span style={{ fontWeight: 600, color: 'var(--color-primary, #2563eb)', minWidth: 100, fontSize: '0.8125rem' }}>{e.code}</span>
                            <span style={{ flex: 1 }}>{e.name}</span>
                            {assignedOther && (
                              <span style={{ fontSize: '0.75rem', color: '#c2410c', maxWidth: 220 }}>
                                Đã cấu hình ở định khoản {e.assignedPostingReasonCode}
                              </span>
                            )}
                            {already && (
                              <span style={{ fontSize: '0.75rem', color: '#16a34a' }}>Đã chọn</span>
                            )}
                            {!disabled && <i className="fas fa-plus" style={{ color: 'var(--color-primary, #2563eb)', fontSize: '0.75rem' }} />}
                          </button>
                        );
                      })}
                    </div>
                  )}
                  {expensePickSearch.trim() && filteredExpenseItems.length === 0 && (
                    <p style={{ margin: '4px 0 0', fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6b7280)' }}>
                      Không tìm thấy khoản chi phí phù hợp.
                    </p>
                  )}
                </div>
              )}

              {selectedExpenseCodes.length === 0 ? (
                <div style={{
                  display: 'flex', alignItems: 'center', gap: 8,
                  padding: '10px 14px',
                  background: 'var(--color-bg-subtle, #f9fafb)',
                  border: '1px solid var(--color-border, #e5e7eb)',
                  borderRadius: 6, fontSize: '0.875rem', color: 'var(--color-text-secondary, #6b7280)',
                }}>
                  Chưa gắn mã chi phí
                </div>
              ) : (
                <>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                    <span style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6b7280)' }}>
                      {selectedExpenseCodes.length} mã chi phí
                    </span>
                    {!viewOnlyShared && (
                      <button
                        type="button"
                        onClick={clearExpenseCodes}
                        style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '0.8125rem', color: 'var(--color-danger, #dc2626)', padding: '2px 4px' }}
                      >
                        Xóa tất cả
                      </button>
                    )}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                    {selectedExpenseCodes.map(code => {
                      const item = expenseItems.find(e => e.code.toUpperCase() === code);
                      return (
                        <div
                          key={code}
                          style={{
                            display: 'flex', alignItems: 'center', gap: 8,
                            padding: '7px 12px',
                            background: 'var(--color-bg-subtle, #f9fafb)',
                            border: '1px solid var(--color-border, #e5e7eb)',
                            borderRadius: 6, fontSize: '0.875rem',
                          }}
                        >
                          <span style={{ fontWeight: 600, color: 'var(--color-primary, #2563eb)', minWidth: 100, fontSize: '0.8125rem' }}>{code}</span>
                          <span style={{ flex: 1 }}>{item?.name ?? code}</span>
                          {!viewOnlyShared && (
                            <button
                              type="button"
                              onClick={() => toggleExpenseCode(code, false)}
                              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '2px 6px', color: 'var(--color-text-secondary, #9ca3af)', fontSize: '1.1rem', lineHeight: 1 }}
                              data-testid={`${TEST_ID}-remove-expense-${code}`}
                            >
                              ×
                            </button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </>
              )}
            </div>
          )}

          {formTab === 'vouchers' && (
            <div style={{ paddingTop: 16 }}>
              <p style={{ margin: '0 0 14px', fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6b7280)' }}>
                Không chọn = áp dụng tất cả loại chứng từ. Chọn để giới hạn lookup khi dùng nghiệp vụ này trên form PT/PC.
              </p>

              {/* Search để thêm chứng từ */}
              {!viewOnlyShared && (
                <div style={{ marginBottom: 14 }}>
                  <SearchTextInput
                    label="Tìm và thêm chứng từ"
                    placeholder="Tìm mã, tên, prefix..."
                    value={voucherPickSearch}
                    onChange={setVoucherPickSearch}
                    onSearch={() => {}}
                    testId={`${TEST_ID}-voucher-pick-search`}
                  />
                  {availableToAdd.length > 0 && (
                    <div style={{
                      border: '1px solid var(--color-border, #e5e7eb)',
                      borderRadius: 6,
                      marginTop: 4,
                      overflow: 'hidden',
                      maxHeight: 200,
                      overflowY: 'auto',
                    }}>
                      {availableToAdd.map(v => (
                        <button
                          key={v.voucherTypeCode}
                          type="button"
                          onClick={() => {
                            toggleAllowedVoucher(v.voucherTypeCode, true);
                            setVoucherPickSearch('');
                          }}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 8,
                            width: '100%',
                            textAlign: 'left',
                            padding: '8px 12px',
                            background: 'none',
                            border: 'none',
                            borderBottom: '1px solid var(--color-border, #e5e7eb)',
                            cursor: 'pointer',
                            fontSize: '0.875rem',
                          }}
                          data-testid={`${TEST_ID}-add-voucher-${v.voucherTypeCode}`}
                        >
                          <span style={{ fontWeight: 600, color: 'var(--color-primary, #2563eb)', minWidth: 100, fontSize: '0.8125rem' }}>
                            {v.voucherTypeCode}
                          </span>
                          <span style={{ flex: 1 }}>{v.name}</span>
                          {v.idCodePrefix && (
                            <span style={{ fontSize: '0.75rem', color: 'var(--color-text-secondary, #6b7280)', background: 'var(--color-bg-subtle, #f3f4f6)', padding: '1px 6px', borderRadius: 4 }}>
                              {v.idCodePrefix}
                            </span>
                          )}
                          <i className="fas fa-plus" style={{ color: 'var(--color-primary, #2563eb)', fontSize: '0.75rem' }} />
                        </button>
                      ))}
                    </div>
                  )}
                  {voucherPickSearch.trim() && availableToAdd.length === 0 && (
                    <p style={{ margin: '4px 0 0', fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6b7280)' }}>
                      Không tìm thấy hoặc đã chọn hết chứng từ phù hợp.
                    </p>
                  )}
                </div>
              )}

              {/* Danh sách đã chọn */}
              {allowedVoucherCodes.length === 0 ? (
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                  padding: '10px 14px',
                  background: 'var(--color-bg-subtle, #f9fafb)',
                  border: '1px solid var(--color-border, #e5e7eb)',
                  borderRadius: 6,
                  fontSize: '0.875rem',
                  color: 'var(--color-text-secondary, #6b7280)',
                }}>
                  <i className="fas fa-check-circle" style={{ color: 'var(--color-success, #16a34a)' }} />
                  Tất cả loại chứng từ (không giới hạn)
                </div>
              ) : (
                <>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 6 }}>
                    <span style={{ fontSize: '0.8125rem', color: 'var(--color-text-secondary, #6b7280)' }}>
                      {allowedVoucherCodes.length} loại chứng từ được chọn
                    </span>
                    {!viewOnlyShared && (
                      <button
                        type="button"
                        onClick={clearAllowedVouchers}
                        style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '0.8125rem', color: 'var(--color-danger, #dc2626)', padding: '2px 4px' }}
                      >
                        Xóa tất cả
                      </button>
                    )}
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                    {allowedVoucherCodes.map(code => {
                      const v = voucherRegistry.find(r => r.voucherTypeCode === code);
                      return (
                        <div
                          key={code}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 8,
                            padding: '7px 12px',
                            background: 'var(--color-bg-subtle, #f9fafb)',
                            border: '1px solid var(--color-border, #e5e7eb)',
                            borderRadius: 6,
                            fontSize: '0.875rem',
                          }}
                        >
                          <span style={{ fontWeight: 600, color: 'var(--color-primary, #2563eb)', minWidth: 120, fontSize: '0.8125rem' }}>
                            {code}
                          </span>
                          <span style={{ flex: 1 }}>{v?.name ?? code}</span>
                          {v?.idCodePrefix && (
                            <span style={{ fontSize: '0.75rem', color: 'var(--color-text-secondary, #6b7280)', background: 'var(--color-bg, #fff)', border: '1px solid var(--color-border, #e5e7eb)', borderRadius: 4, padding: '1px 6px' }}>
                              {v.idCodePrefix}
                            </span>
                          )}
                          {!viewOnlyShared && (
                            <button
                              type="button"
                              onClick={() => toggleAllowedVoucher(code, false)}
                              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '2px 6px', color: 'var(--color-text-secondary, #9ca3af)', fontSize: '1.1rem', lineHeight: 1 }}
                              data-testid={`${TEST_ID}-remove-voucher-${code}`}
                            >
                              ×
                            </button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </>
              )}
            </div>
          )}

          <CatalogCompanyField
            testIdPrefix={TEST_ID}
            companyName={editing?.companyName ?? sessionCompanyName}
          />
          <SharedCatalogFormActions
            testIdPrefix={TEST_ID}
            row={editing}
            currentValues={{
              name: form.name,
              debitAccountCode: form.debitAccountCode,
              creditAccountCode: form.creditAccountCode,
            }}
            {...sharedForm}
          />
          <div className={styles.modalActions}>
            <CatalogFormHistorySlot
              testIdPrefix={TEST_ID}
              catalogKind={CATALOG_KIND}
              editing={editing ? { id: editing.id, code: editing.code } : null}
            />
            <Button variant="secondary" onClick={closeFormModal}>Hủy</Button>
            <Button
              variant="primary"
              onClick={handleSave}
              disabled={saving || viewOnlyShared}
              data-testid={`${TEST_ID}-save-btn`}
            >
              {saving ? 'Đang lưu...' : 'Lưu'}
            </Button>
          </div>
        </div>
      </Modal>
    </>
  );
};

export default DinhKhoanNghiepVuPage;
